commands.text:
✅️ noncomputable def path (c : Change S T) {p : StatePackage S} {q : StatePackage T}
        (h : Preserves (carrier c) p q) : PackagePath c p q :=
      (packageIdentity c p q).symm h

✅️ theorem transport_of_preserves (c : Change S T) {p : StatePackage S}
        {q : StatePackage T} (h : Preserves (carrier c) p q) : transport c p = q :=
      (transport_eq c p).trans h.package_eq

✅️ theorem path_recovery (c : Change S T) {p : StatePackage S} {q : StatePackage T}
        (r : PackagePath c p q) : path c (packageIdentity c p q r) = r :=
      (packageIdentity c p q).symm_apply_apply r

